import{_ as e,o,c as t,k as r}from"./chunks/framework.ystBm8og.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1785751237000}'),i={name:"faq.md"};function s(n,a,h,d,l,p){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-pomodoro-free" tabindex="-1">Is Pomodoro free? <a class="header-anchor" href="#is-pomodoro-free" aria-label="Permalink to &quot;Is Pomodoro free?&quot;">​</a></h2><p>Yes. The app is open source under the <a href="https://github.com/nikhilakki/pomodoro/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a>.</p><h2 id="which-platforms-are-supported" tabindex="-1">Which platforms are supported? <a class="header-anchor" href="#which-platforms-are-supported" aria-label="Permalink to &quot;Which platforms are supported?&quot;">​</a></h2><p>macOS (Apple Silicon and Intel), Windows (x64 and arm64), and Linux (x64 and arm64). See <a href="/guide/install">Install</a>.</p><h2 id="why-does-macos-say-the-app-is-damaged" tabindex="-1">Why does macOS say the app is damaged? <a class="header-anchor" href="#why-does-macos-say-the-app-is-damaged" aria-label="Permalink to &quot;Why does macOS say the app is damaged?&quot;">​</a></h2><p>Unsigned downloads are quarantined by Gatekeeper. Clear quarantine once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Pomodoro.app</span></span></code></pre></div><p>Details: <a href="/guide/install#macos">Install → macOS</a>.</p><h2 id="why-can-t-i-drag-the-window" tabindex="-1">Why can’t I drag the window? <a class="header-anchor" href="#why-can-t-i-drag-the-window" aria-label="Permalink to &quot;Why can’t I drag the window?&quot;">​</a></h2><p>Use the title bar strip or empty area around the timer (and the ring). Toolbar buttons are not drag handles. Fixed in <strong>v0.1.1</strong> for overlay title bars.</p><h2 id="where-is-my-data-stored" tabindex="-1">Where is my data stored? <a class="header-anchor" href="#where-is-my-data-stored" aria-label="Permalink to &quot;Where is my data stored?&quot;">​</a></h2><p>On your device only - settings/tasks in a local store, session history in SQLite. See <a href="/guide/privacy">Privacy</a>.</p><h2 id="does-it-sync-across-devices" tabindex="-1">Does it sync across devices? <a class="header-anchor" href="#does-it-sync-across-devices" aria-label="Permalink to &quot;Does it sync across devices?&quot;">​</a></h2><p>No. There is no cloud sync. You can back up the app data directory yourself if needed.</p><h2 id="can-i-change-the-25-5-15-defaults" tabindex="-1">Can I change the 25/5/15 defaults? <a class="header-anchor" href="#can-i-change-the-25-5-15-defaults" aria-label="Permalink to &quot;Can I change the 25/5/15 defaults?&quot;">​</a></h2><p>Yes - open <strong>Settings</strong> (gear or <code>⌘,</code> on macOS) and edit phase lengths and long-break cadence.</p><h2 id="how-do-i-contribute" tabindex="-1">How do I contribute? <a class="header-anchor" href="#how-do-i-contribute" aria-label="Permalink to &quot;How do I contribute?&quot;">​</a></h2><ol><li>Fork <a href="https://github.com/nikhilakki/pomodoro" target="_blank" rel="noreferrer">nikhilakki/pomodoro</a></li><li>Follow <a href="/develop/setup">Setup from source</a></li><li>Open a pull request with a clear description</li></ol><p>Docs improvements: edit this site’s repo (<a href="https://github.com/nikhilakki/pomodoro-docs" target="_blank" rel="noreferrer">pomodoro-docs</a>) or use <strong>Edit this page</strong> on any article.</p><h2 id="who-maintains-this" tabindex="-1">Who maintains this? <a class="header-anchor" href="#who-maintains-this" aria-label="Permalink to &quot;Who maintains this?&quot;">​</a></h2><p><strong>nikhilakki</strong> - <a href="https://github.com/nikhilakki" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://x.com/nik_akki" target="_blank" rel="noreferrer">@nik_akki</a></p><h2 id="where-do-i-report-bugs" tabindex="-1">Where do I report bugs? <a class="header-anchor" href="#where-do-i-report-bugs" aria-label="Permalink to &quot;Where do I report bugs?&quot;">​</a></h2><p>Open an issue on <a href="https://github.com/nikhilakki/pomodoro/issues" target="_blank" rel="noreferrer">github.com/nikhilakki/pomodoro</a> with OS, arch, app version, and steps to reproduce.</p>',24)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
